#!/usr/bin/env python3
"""One continuous native clock, locked story views and short synchronized dissolves."""
import argparse, hashlib, importlib.util, json, subprocess
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont
parser=argparse.ArgumentParser();parser.add_argument('--project',type=Path,required=True);args=parser.parse_args();p=args.project.resolve()
spec=importlib.util.spec_from_file_location('edit',p/'scripts/edit.py');edit=importlib.util.module_from_spec(spec);spec.loader.exec_module(edit);edit.PROJECT=p
frames=610;duration=frames/60
key='vocal-story-capture-v2/vocal-story';catalog=edit.sources();clip=catalog[key];source=Path(clip['path']);receipt=clip['receipt'];assert edit.digest(source)==receipt['sha256']
assert abs(receipt['nativeMusic']['offset']-20.68)<.000001
assert clip['source']['visualFixes']['combatTextBaseSize']==38.4 and clip['source']['visualFixes']['earthElementalBattleMirroring']
assert edit.digest(p/'audio/countess.mp3')=='acfc64cba056fab100911b8fa805f60c8af910c8947843dbc57902c2b24ecbad'
id='07-countess-vocal-story';rev='v1';out=p/'finals'/f'{id}-{rev}.mp4';review=p/'review'/f'{id}-{rev}';review.mkdir(parents=True,exist_ok=True)
if out.exists():raise RuntimeError('Preserve the existing candidate;use a new revision')
timeline={'id':id,'duration':duration,'fps':60,'source':key,'music':{'file':'audio/countess.mp3','in':20.68,'fade':.12},'sfx':.42,'sfxMode':'tails','shots':[{'source':key,'in':0,'duration':duration}], 'views':[{'name':'Countess vocal introduction','sourceFrames':[0,71],'zoom':2.1,'focus':[.70,.32]},{'name':'Establish player,board and defensive setup','sourceFrames':[65,325],'zoom':1.12,'focus':[.49,.57]},{'name':'Shield Bash inspection:Block becomes damage','sourceFrames':[319,386],'zoom':1.45,'focus':[.505,.72]},{'name':'Return to context for actual impact and Sunder','sourceFrames':[380,frames],'zoom':1.12,'focus':[.49,.57]}], 'transitions':[{'kind':'synchronized dissolve','frames':[65,71]},{'kind':'synchronized dissolve','frames':[319,325]},{'kind':'synchronized dissolve','frames':[380,386]}], 'introLogo':{'file':'graphics/logo.webp','position':[60,45],'width':480,'fadeIn':[0,.15],'fadeOut':[.75,.95]}, 'rules':{'sameNativeFrameAcrossDissolves':True,'retiming':False,'animatedCamera':False,'featureInserts':False,'nativeLyrics':True},'listeningApproval':False,'scope':'Short story/style excerpt,not a complete trailer. Ends after third native lyric line at song30.847s,before the next lyric begins.'}
edit.write(p/'timelines'/f'{id}.json',timeline)
pcm=edit.audio(timeline,catalog,rev)
def view(label,name,first,last,z,cx,cy):
 return f"[{label}]trim=start_frame={first}:end_frame={last},setpts=PTS-STARTPTS,crop=w='floor(iw/{z}/32)*32':h='floor(ih/{z}/18)*18':x='floor(max(0,min(iw-ow,iw*{cx}-ow/2))/2)*2':y='floor(max(0,min(ih-oh,ih*{cy}-oh/2))/2)*2',scale=1920:1080:flags=lanczos:out_color_matrix=bt709,setsar=1,format=yuv444p[{name}]"
filters=['[0:v]split=4[fa][w1][ha][w2]',view('fa','face',0,71,2.1,.70,.32),view('w1','wide1',65,325,1.12,.49,.57),view('ha','hand',319,386,1.45,.505,.72),view('w2','wide2',380,frames,1.12,.49,.57),f'[face][wide1]xfade=transition=fade:duration=0.1:offset={65/60}[x1]',f'[x1][hand]xfade=transition=fade:duration=0.1:offset={319/60}[x2]',f'[x2][wide2]xfade=transition=fade:duration=0.1:offset={380/60}[x3]','[1:v]scale=480:-1:flags=lanczos,format=rgba,fade=t=in:st=0:d=0.15:alpha=1,fade=t=out:st=0.75:d=0.2:alpha=1[logo]',"[x3][logo]overlay=x=60:y=45:enable='lt(t,1)':shortest=1,fade=t=in:st=0:d=0.18,format=yuv420p,setparams=range=limited:color_primaries=bt709:color_trc=bt709:colorspace=bt709[out]"]
edit.ff(['-i',source,'-loop',1,'-framerate',60,'-i',p/'graphics/logo.webp','-i',pcm,'-filter_complex_threads',1,'-filter_complex',';'.join(filters),'-map','[out]','-map','2:a','-frames:v',frames,'-t',duration,'-r',60,'-c:v','libx264','-preset','fast','-profile:v','high','-level:v','4.2','-b:v','20M','-maxrate','24M','-bufsize','40M','-g',120,'-pix_fmt','yuv420p','-colorspace','bt709','-color_primaries','bt709','-color_trc','bt709','-bsf:v','h264_metadata=colour_primaries=1:transfer_characteristics=1:matrix_coefficients=1','-threads',2,'-c:a','aac','-b:a','192k','-ar',48000,'-ac',2,'-movflags','+faststart',out])
preview=review/'alchemy-countess-vocal-story-v1-chat-1080p60.mp4'
edit.ff(['-i',out,'-map','0:v','-map','0:a','-c:v','libx264','-preset','fast','-profile:v','high','-level:v','4.2','-b:v','9M','-maxrate','12M','-bufsize','18M','-g',120,'-pix_fmt','yuv420p','-colorspace','bt709','-color_primaries','bt709','-color_trc','bt709','-bsf:v','h264_metadata=colour_primaries=1:transfer_characteristics=1:matrix_coefficients=1','-threads',2,'-c:a','copy','-movflags','+faststart',preview])
meta=edit.probe(out,True);v=next(x for x in meta['streams']if x['codec_type']=='video');a=next(x for x in meta['streams']if x['codec_type']=='audio');assert(v['width'],v['height'],v['r_frame_rate'],int(v['nb_read_frames']))==(1920,1080,'60/1',frames);assert(a['codec_name'],a['sample_rate'],a['channels'])==('aac','48000',2)
assert preview.stat().st_size<20_000_000
raw=lambda f:subprocess.check_output(['ffmpeg','-v','error','-i',str(f),'-vn','-c:a','copy','-f','adts','pipe:1'])
assert hashlib.sha256(raw(out)).digest()==hashlib.sha256(raw(preview)).digest()
log=edit.ff(['-i',out,'-af','ebur128=peak=true','-f','null','-'],True);(review/'audio-measurement.txt').write_text(log[-1600:])
times=[.5,1.5,2.8,4.55,5.8,6.8,8.4,9.6];sheet=Image.new('RGB',(1600,2*250),'#0a0d10');d=ImageDraw.Draw(sheet);font=ImageFont.truetype(str(p/'graphics/Inter.woff2'),17)
for i,t in enumerate(times):
 file=review/f'frame-{t:.3f}.png';edit.ff(['-ss',t,'-i',out,'-frames:v',1,file]);im=Image.open(file).convert('RGB').resize((400,225),Image.Resampling.LANCZOS);x=(i%4)*400;y=(i//4)*250;sheet.paste(im,(x,y));d.text((x+10,y+228),f'{t:.2f}s / song{20.68+t:.2f}s',font=font,fill='#ead7b7')
contact=review/'countess-vocal-story-v1-contact.jpg';sheet.save(contact,quality=92)
record={'master':str(out.relative_to(p)),'sha256':edit.digest(out),'preview':str(preview.relative_to(p)),'previewSha256':edit.digest(preview),'previewBytes':preview.stat().st_size,'contact':str(contact.relative_to(p)),'dimensions':[1920,1080],'fps':60,'frames':frames,'duration':duration,'sourceSongRange':[20.68,20.68+duration],'source':clip['source'],'sourceSha256':receipt['sha256'],'audioPacketsIdentical':True,'fullSequentialDecode':True,'listeningApproval':False,'metadata':meta,'timeline':timeline};edit.write(out.with_suffix('.json'),record);edit.write(review/'technical.json',record);print(json.dumps({k:record[k]for k in ['master','preview','previewBytes','contact','duration','frames']},indent=2),flush=True)
